{
  "assessments": [
    {
      "proposition_id": "P1",
      "status": "full",
      "summary_quote": "It would allow a public charter school authorized by the commission and the local board of education of the local education agency (LEA) where the school is located to mutually agree in writing, within 30 calendar days of authorization, that the local board of education will serve as both the authorizer and the LEA. In this case, the local board would take over the rights and responsibilities of the charter agreement, which must be filed with the commission. This option is not available to schools that had their charter agreement renewed on appeal by the commission.",
      "rationale": "Conveys the eligible parties, written mutual agreement, deadline, local board's roles and responsibilities, and exclusion for renewals approved on appeal."
    },
    {
      "proposition_id": "P2",
      "status": "partial",
      "summary_quote": "the charter agreement, which must be filed with the commission",
      "rationale": "Includes the filing requirement but omits that filing must follow the manner prescribed by the commission."
    },
    {
      "proposition_id": "P3",
      "status": "partial",
      "summary_quote": "The bill also changes certain technical references to \"initial charter agreements\"",
      "rationale": "Conveys the change to initial charter agreements but does not identify § 49-13-110(b)(1), whose affected provision cannot otherwise be identified from the supplied bill."
    },
    {
      "proposition_id": "P4",
      "status": "full",
      "summary_quote": "Additionally, the bill would specify that if a local board of education approves a charter school renewal application, the renewed agreement must last for 10 academic years.",
      "rationale": "Conveys the local-board approval condition and mandatory 10-academic-year renewal term."
    },
    {
      "proposition_id": "P5",
      "status": "partial",
      "summary_quote": "If the commission approves the renewal, the term must be between five and ten academic years, as decided by the commission.",
      "rationale": "Conveys the approval condition, term range, and commission's authority, but omits the requirement that the term be determined by commission resolution."
    },
    {
      "proposition_id": "P6",
      "status": "partial",
      "summary_quote": "removes specific \"notwithstanding\" clauses in the law",
      "rationale": "Mentions removal of notwithstanding clauses but does not identify the affected provisions, §§ 49-13-121(f)(3) and 49-13-121(l), or the language being replaced with \"If\"."
    },
    {
      "proposition_id": "P7",
      "status": "full",
      "summary_quote": "These changes would take effect immediately upon becoming law.",
      "rationale": "Conveys the act's effective date upon becoming law."
    }
  ]
}
